{
    base.OnKeyDown(e);
    ConfigureInputRouter();
    if (_input?.KeyDown(MapInputKey(e.Key), ToHavenModifiers(e.KeyModifiers)) != true) return;
    e.Handled = true;
    InvalidateMeasure();
    InvalidateScene();
}

